assignment.solutionCode:
class Battery {
  constructor(capacity) {
    this.capacity = capacity;
    this._level = 0;
  }

  get level() {
    return this._level;
  }

  set level(value) {
    this._level = Math.max(0, Math.min(this.capacity, value));
  }

  static full(capacity) {
    const battery = new Battery(capacity);
    battery.level = capacity;
    return battery;
  }
}

function runBatteryDemo(capacity) {
  const pack = Battery.full(capacity);
  pack.level = capacity + 50;
  console.log(pack.level);
}

